package main

import (
	"fmt"
	"os"
	"strconv"
)

func main() {
	if len(os.Args) < 2 {
		return
	}

	n, err := strconv.Atoi(os.Args[1])
	if err != nil {
		return
	}

	if n < 2 {
		return
	}

	// Sieve of Eratosthenes
	isPrime := make([]bool, n+1)
	for i := range isPrime {
		isPrime[i] = true
	}
	isPrime[0] = false
	isPrime[1] = false

	for i := 2; i*i <= n; i++ {
		if isPrime[i] {
			for j := i * i; j <= n; j += i {
				isPrime[j] = false
			}
		}
	}

	for i := 2; i <= n; i++ {
		if isPrime[i] {
			fmt.Println(i)
		}
	}
}
```

This program:
1. Reads a single integer `N` from the command line arguments.
2. If `N < 2`, there are no primes to print, so it outputs nothing.
3. Otherwise, it uses the **Sieve of Eratosthenes** to efficiently mark all non-prime numbers up to `N`.
4. It then iterates from 2 to `N` (inclusive) and prints each prime number on its own line.

