using System;

int N = int.Parse(Args[0]);

for (int i = 2; i <= N; i++)
{
    if (IsPrime(i))
    {
        Console.WriteLine(i);
    }
}

static bool IsPrime(int n)
{
    if (n < 2) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int d = 3; (long)d * d <= n; d += 2)
    {
        if (n % d == 0) return false;
    }
    return true;
}
```

This script reads a single integer `N` from the command line arguments, then iterates through all integers from 2 to `N` (inclusive). For each number, it checks primality using trial division up to the square root. Only primes are printed, one per line. If `N` is less than 2, the loop never executes and nothing is printed.

